/**
 * Command-line utility to parse .svdat files and summarize decoded events.
 * Usage: tsx scripts/parse-svdat.ts <file.svdat> [more.svdat ...]
 *          [--limit N] [--filter substr] [--elf app.elf] [--syms nm.txt]
 *
 * `--elf` loads an application ELF file to resolve address parameters to symbol
 * names and verify the ELF SHA-256 hash against ELF_SHA256 in the trace.
 * `--syms` parses an address-to-name symbol map generated by riscv32-esp-elf-nm.
 */
import { readFileSync } from "node:fs";

import { type ElfSymbols, parseElfSymbols, sha256Hex, verifyElfHash } from "../src/elf/index.js";
import { parseTraceFiles, traceElfSha256 } from "../src/trace/index.js";

const args = process.argv.slice(2);
const files: string[] = [];
let limit = 40;
let filter: string | null = null;
let symsFile: string | null = null;
let elfFile: string | null = null;
for (let i = 0; i < args.length; i++) {
  if (args[i] === "--limit") limit = Number(args[++i]);
  else if (args[i] === "--filter") filter = args[++i]!;
  else if (args[i] === "--syms") symsFile = args[++i]!;
  else if (args[i] === "--elf") elfFile = args[++i]!;
  else files.push(args[i]!);
}

// Optional address-to-name map from `riscv32-esp-elf-nm <elf>` output, used to
// symbolize the user_id of svUserStart and svUserStop (instrumented function address).
const syms = new Map<number, string>();
if (symsFile) {
  for (const line of readFileSync(symsFile, "utf8").split("\n")) {
    const m = line.match(/^([0-9a-fA-F]+)\s+\S\s+(\S+)/);
    if (m) syms.set(parseInt(m[1]!, 16), m[2]!);
  }
}

async function main(): Promise<void> {
  // When provided, use the ELF file to symbolize addresses and verify against the
  // SHA-256 hash embedded in the trace.
  let elf: ElfSymbols | undefined;
  let elfBytes: Uint8Array | undefined;
  if (elfFile) {
    elfBytes = new Uint8Array(readFileSync(elfFile));
    elf = parseElfSymbols(elfBytes);
  }

  const symbolize = (v: number): string => {
    const a = v >>> 0;
    if (elf) {
      const hit = elf.lookup(a);
      if (hit) return hit.offset === 0 ? hit.name : `${hit.name}+0x${hit.offset.toString(16)}`;
    }
    return syms.get(a) ?? `0x${a.toString(16)}`;
  };

  const buffers = files.map((f) => new Uint8Array(readFileSync(f)));
  const model = parseTraceFiles(buffers, elf ? { elf } : {});

  console.log(`files: ${files.join(", ")}`);
  console.log(`total events: ${model.events.length}`);

  // Report the trace SHA-256 hash and ELF hash verification result.
  const traceHash = traceElfSha256(model);
  if (elfBytes) {
    const verdict = verifyElfHash(traceHash, await sha256Hex(elfBytes));
    console.log(
      `elf: ${elfFile} (${elf!.symbolCount} symbols); trace ELF_SHA256=${traceHash ?? "none"} → ${verdict}`,
    );
  } else if (traceHash) {
    console.log(`trace ELF_SHA256=${traceHash} (no --elf given to verify against)`);
  }

  // Event count by name
  const hist = new Map<string, number>();
  for (const e of model.events) hist.set(e.name, (hist.get(e.name) ?? 0) + 1);
  console.log("\nevent histogram:");
  for (const [name, n] of [...hist.entries()].sort((a, b) => b[1] - a[1]))
    console.log(`  ${String(n).padStart(6)}  ${name}`);

  const shown = filter ? model.events.filter((e) => e.name.includes(filter!)) : model.events;
  console.log(`\nfirst ${Math.min(limit, shown.length)} events${filter ? ` matching "${filter}"` : ""}:`);
  let depth = 0;
  for (const e of shown.slice(0, limit)) {
    const isUser = e.name === "svUserStart" || e.name === "svUserStop";
    if (e.name === "svUserStop") depth = Math.max(0, depth - 1);
    const params = Object.entries(e.params)
      .map(([k, v]) =>
        isUser && k === "user_id" ? `${k}=${symbolize(Number(v))}` : `${k}=${v}`,
      )
      .join(" ");
    const indent = isUser ? "  ".repeat(depth) : "";
    console.log(
      `  ${e.ts.toFixed(6)}s core${e.coreId} [${e.ctxName}]${e.inIrq ? " IRQ" : ""} ${indent}${e.name}${params ? " {" + params + "}" : ""}`,
    );
    if (e.name === "svUserStart") depth++;
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
